from typing import Optional
from pydantic import BaseModel, Field

class MixedParamsModel(BaseModel):
    path_id: str = Field(..., description="Path parameter ID")
    query_limit: int = Field(default=10, gt=0, description="Query limit with constraint")
    body_name: Optional[str] = Field(None, max_length=50, description="Optional body name")

def build_model(path_id: str, query_limit: int, body_name: Optional[str] = None) -> dict:
    model = MixedParamsModel(
        path_id=path_id,
        query_limit=query_limit,
        body_name=body_name
    )
    return model.model_dump(mode="json")

from typing import List, Set
from pydantic import BaseModel

class Item(BaseModel):
    name: str
    value: float

class ComplexData(BaseModel):
    items: List[Item]
    tags: Set[str]
    metadata: dict

def create_complex_data(item_names: list, item_values: list, tag_list: list, meta_dict: dict) -> dict:
    try:
        items = [Item(name=name, value=value) for name, value in zip(item_names, item_values)]
        tags = set(tag_list)
        return ComplexData(items=items, tags=tags, metadata=meta_dict).model_dump(mode='json')
    except Exception as e:
        return {'error': str(e)}

